#include <iostream>
using namespace std;

int main() {
    bool valid = true;
    char str[9];

    for (int count = 0; count < 8; ++count) {
        scanf("%8s", str);
        for (int i = 0; i < 8; i += 2) {
            if (str[i] == str[i + 1]) {
                valid = false;
            }
        }
    }

    cout << (valid ? "YES" : "NO");
    return 0;
}

